    <script>
        const sudoku = document.getElementById('sudoku');
        const numbers = Array.from(Array(9).keys()).map(n => String.fromCharCode(n + 48));

        // Precompiled cells
        const precompiled = [
            [null, 3, 6, null, null, null, null, 9, null],
            [5, 7, null, null, null, null, 4, null, null],
